import {writeFileSync} from 'node:fs';
import {SqliteOfflineQueue,OfflineRetentionWorker} from '../../dist/index.js';
const [path,barrier,action,phase,id]=process.argv.slice(2),scope={tenantId:'tenant',applicationId:'app'},queue=new SqliteOfflineQueue(path,{enabled:true,maxAttempts:2,retryDelayMs:0}),evidence={operatorId:'operator',reference:'case'};
const hold=()=>{writeFileSync(barrier,phase);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0);};
try{if(phase==='during'){queue.db.function('test_offline_evidence_barrier',()=>{hold();return 0;});queue.db.exec((action==='archive'||action==='retention')?'CREATE TRIGGER test_offline_evidence_crash BEFORE DELETE ON offline_operations BEGIN SELECT test_offline_evidence_barrier(); END':'CREATE TRIGGER test_offline_evidence_crash BEFORE INSERT ON offline_recovery_events BEGIN SELECT test_offline_evidence_barrier(); END');}if(action==='recover')queue.recoverAbandonedWithEvidence(scope,'owner',id,evidence,10);else if(action==='archive')queue.archiveTerminal(scope,'owner',id,evidence,10);else if(action==='retention'){const worker=new OfflineRetentionWorker({queue,scope,queuePrincipalId:'owner',operationId:'change',operatorId:evidence.operatorId,reference:evidence.reference,minAgeMs:100,maxPerPass:10,pollMs:100,authorize:()=>true,onError:error=>{throw error;},now:()=>1000});if(await worker.runOnce()!==1)throw Error('Expected retirement');}else queue.reconcileWithEvidence(scope,'owner',id,'applied',evidence,10);if(phase==='after')hold();throw Error('Expected process termination');}catch(error){process.send?.({error:String(error)});process.exitCode=1;}finally{queue.close();}
